//! Independent real-checkpoint parity for Pipecat SmartTurn v2.
//!
//! The committed fixture is generated by
//! `tools/parity/smart_turn_prepare_checkpoint.py`, which executes the pinned
//! official Transformers Wav2Vec2 backbone and Pipecat endpoint head. The
//! 362 MiB GGUF is intentionally not committed; set `VOKRA_SMART_TURN_GGUF`
//! to the converted canonical artifact to run the real-checkpoint leg.

use std::path::Path;

use vokra_models::smart_turn::SmartTurn;

const PCM_BYTES: &[u8] = include_bytes!("fixtures/smart_turn/pcm_1s.f32.bin");
const PROBABILITY_BYTES: &[u8] =
    include_bytes!("fixtures/smart_turn/completion_probability.f32.bin");

fn decode_f32(bytes: &[u8]) -> Vec<f32> {
    assert_eq!(
        bytes.len() % 4,
        0,
        "fixture byte length must be f32-aligned"
    );
    bytes
        .chunks_exact(4)
        .map(|chunk| f32::from_le_bytes([chunk[0], chunk[1], chunk[2], chunk[3]]))
        .collect()
}

#[test]
fn canonical_checkpoint_matches_official_endpoint_probability() {
    let Some(path) = std::env::var_os("VOKRA_SMART_TURN_GGUF") else {
        eprintln!(
            "[parity_smart_turn] SKIP: set VOKRA_SMART_TURN_GGUF to the converted pinned \
             pipecat-ai/smart-turn-v2 artifact"
        );
        return;
    };
    let model = SmartTurn::from_path(Path::new(&path)).expect("bind canonical SmartTurn GGUF");
    let pcm = decode_f32(PCM_BYTES);
    let expected = decode_f32(PROBABILITY_BYTES)[0];
    let actual = model
        .predict_endpoint(&pcm, 16_000)
        .expect("run native SmartTurn forward")
        .completion_probability();
    let max_abs = (actual - expected).abs();
    eprintln!(
        "[parity_smart_turn] rust={actual:.9e} transformers={expected:.9e} \
         max_abs={max_abs:.9e}"
    );

    // Fixed before the native measurement. Widening this implementation
    // target requires a new independent fixture and review.
    const ATOL: f32 = 1.0e-4;
    assert!(
        max_abs <= ATOL,
        "SmartTurn probability exceeds the independent Transformers parity gate: \
         max_abs={max_abs:.9e}, atol={ATOL:.9e}"
    );
}

#[test]
fn committed_fixture_has_the_pinned_shape() {
    assert_eq!(decode_f32(PCM_BYTES).len(), 16_000);
    let probability = decode_f32(PROBABILITY_BYTES);
    assert_eq!(probability.len(), 1);
    assert!((0.0..=1.0).contains(&probability[0]));
}
